@'
import ast, hashlib, io, os, sqlite3, tempfile
from pathlib import Path
from urllib.parse import parse_qsl, urlencode, urlsplit, urlunsplit
class FakeStreamlit:
    def __init__(self):
        self.messages=[]
        self.context=type('Context', (), {'url':'https://truetone.example/'})()
    def success(self, text): self.messages.append(('success', text))
    def caption(self, text): self.messages.append(('caption', text))
    def write(self, text): self.messages.append(('write', text))
tree=ast.parse(Path('app.py').read_text(encoding='utf-8'))
names={'calculer_empreinte','rechercher_depot_verification','afficher_resultat_verification','creer_url_verification'}
functions=[n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name in names]
namespace={'hashlib':hashlib,'sqlite3':sqlite3,'REGISTRE_DB':None,'st':FakeStreamlit(),'os':os,'parse_qsl':parse_qsl,'urlencode':urlencode,'urlsplit':urlsplit,'urlunsplit':urlunsplit}
exec(compile(ast.Module(body=functions,type_ignores=[]),'app.py','exec'),namespace)
database=Path(tempfile.mktemp(suffix='.db'))
try:
    namespace['REGISTRE_DB']=database
    payload=b'test data'*200000; file=io.BytesIO(payload); file.name='test.wav'
    digest=namespace['calculer_empreinte'](file)
    assert digest==hashlib.sha256(payload).hexdigest() and file.tell()==0
    connection=sqlite3.connect(database)
    try:
        connection.execute('CREATE TABLE depots (numero_certificat TEXT, date_utc TEXT, artiste TEXT, titre TEXT, ia_utilisee TEXT, etapes_ia TEXT, empreinte TEXT)')
        connection.execute('INSERT INTO depots VALUES (?,?,?,?,?,?,?)',('TT-2026-123456','2026-01-02T03:04:05+00:00','Artiste','Titre','oui','Composition',digest))
        connection.commit()
    finally: connection.close()
    assert namespace['rechercher_depot_verification']('TT-2026-123456')[0]=='TT-2026-123456'
    assert namespace['rechercher_depot_verification'](digest,True)[0]=='TT-2026-123456'
    assert namespace['rechercher_depot_verification']('absent') is None
    namespace['st']=FakeStreamlit(); namespace['afficher_resultat_verification'](namespace['rechercher_depot_verification'](digest,True))
    assert ('success','Fichier enregistré') in namespace['st'].messages
    assert any('Déclaration IA' in m[1] and 'Composition' in m[1] for m in namespace['st'].messages if m[0]=='write')
    namespace['st']=FakeStreamlit(); namespace['afficher_resultat_verification'](None)
    assert ('caption','Aucun enregistrement trouvé') in namespace['st'].messages
    namespace['st']=FakeStreamlit(); link=namespace['creer_url_verification']('TT-2026-123456')
    assert dict(parse_qsl(urlsplit(link).query))['certificat']=='TT-2026-123456'
    print('Verification tests passed: SHA-256, certificate/hash lookups, match/no-match display, and QR URL parameter.')
finally:
    if database.exists(): database.unlink()
'@ | & .\.venv\Scripts\python.exe -

